namespace {
struct Parts { double revenue=0, facility=0, inventory=0, supplier=0, market=0, investment=0; };
std::string join(const std::vector<int>& v) { std::ostringstream s; for(size_t i=0;i<v.size();++i){if(i)s<<";";s<<v[i];} return s.str(); }
std::string joinS(const std::vector<std::string>& v) { std::ostringstream s; for(size_t i=0;i<v.size();++i){if(i)s<<";";s<<v[i];} return s.str(); }
Parts objectiveParts(const Instance& x,const Solution& sol,const Config& c) {
 Parts z; for(const auto& d:sol.dcSolutions){int j=d.dcIndex; std::vector<int>S=d.S; double D=InventoryCostFormula::totalDemand(x,j,S); z.revenue+=RevenueFormula::totalRevenue(x,j,S,d.p); z.facility+=FacilityCostFormula::totalFixedCost(x,j,d.w); z.inventory+=InventoryCostFormula::totalInventoryCost(x,j,S,d.w); z.supplier+=TransportCostFormula::getSupplierDCTransportCostPerTonne(x,j)*D; for(int i=0;i<x.numRetailer;++i)if(S[i])z.market+=TransportCostFormula::getDCMarketTransportCostPerTonne(x,i,j)*x.mu[i]; z.supplier += x.p*(1.0-d.w)*x.b[j]*D; for(int i=0;i<x.numRetailer;++i)if(S[i])z.market += x.p*(1.0-d.w)*x.bb[i][j]*x.mu[i]; z.investment+=InvestmentCostFormula::compute(x,j,d.w,D,c.use_sqrt_investment,c.investment_exponent);} return z;
}
struct Emissions { double facility=0, inventory=0, supplier=0, market=0; };
Emissions emissionParts(const Instance& x,const PostProcessor& pp) {
 Emissions e; for(const auto& d:pp.dcResults){if(!d.isOpen) continue; int j=d.index; double f=1.0-d.w; std::vector<int>S(x.numRetailer,0); for(int i:d.servedRetailers) S[i]=1; e.facility += f*x.fc[j]; e.supplier += f*x.b[j]*d.D; for(int i:d.servedRetailers) e.market += f*x.bb[i][j]*x.mu[i]; double var=InventoryCostFormula::totalVariance(x,j,S); double ss=x.z_alpha*std::sqrt(x.L[j]*var); e.inventory += f*x.hat_h*(ss + (d.Q_star>0?d.Q_star/2.0:0.0)); } return e;
}
void writeDry(const std::string& out,const Loaded& L,double dist,double cap){std::filesystem::create_directories(out);std::ofstream m(out+"/DRY_RUN_MANIFEST.txt");m<<"supplier_count=1\ncandidate_dc_count=8\nmarket_count=15\nsupplier_dc_arc_count=8\ndc_market_arc_count=120\nbest_w_expected_length=8\ntransport_cost_mode=EXPLICIT_ARC_COST\ncarbon_price=2\ncarbon_quota="<<cap<<"\nw_mode=OPTIMIZED\nintracity_distance_km="<<dist<<"\nGA_invoked=false\nBP_invoked=false\nCPLEX_optimization_invoked=false\nvalidation_status=PASS\n"; std::ofstream a(out+"/solver_arc_parameters.csv");a<<"dc_index,dc_id,market_index,market_id,physical_distance_km,transport_cost_coefficient,transport_emission_coefficient\n";for(int j=0;j<L.inst.numDC;++j)for(int i=0;i<L.inst.numRetailer;++i)a<<j<<","<<L.dc[j]<<","<<i<<","<<L.market[i]<<","<<L.inst.dist[i][j]<<","<<L.inst.dcMarketTransportCostPerTonne[i][j]<<","<<L.inst.bb[i][j]<<"\n";}
Config formalConfig(const Instance& x,int seed,double p,double cap){Config c;c.num_dc=x.numDC;c.num_retailers=x.numRetailer;c.population_size=30;c.max_generation=50;c.crossover_rate=.7;c.mutation_rate=-1;c.elitism=true;c.chromosome_length=10;c.min_w=0;c.max_w=1;c.random_seed=seed;c.carbon_price=p;c.carbon_cap=cap;c.delta=3000;c.investment_exponent=.5;c.rc_eps=1e-6;c.max_branch_nodes=10000;c.max_cg_iterations=2000;c.bp_time_limit_sec=600;c.bp_relative_gap=0;c.cg_early_stop=false;c.dual_smooth_alpha=0;c.use_sqrt_investment=true;c.use_invest_in_column=true;c.pricing_algorithm=0;c.pricing_max_cols_per_dc=3;c.pricing_adaptive_cols=false;c.pricing_per_dc_by_w=false;c.parallel_fitness=true;c.num_threads=8;c.parallel_pricing=false;c.cplex_threads=1;c.pricing_threads=4;c.core_budget=0;c.early_stop=true;c.convergence_generations=10;c.convergence_tolerance=.001;c.root_heuristic=true;c.root_rmp_mip_heuristic=false;c.root_rmp_mip_time_limit_sec=5;c.bb_node_strategy="hybrid";c.bb_hybrid_switch_gap=.01;c.bb_hybrid_dfs_quota=3;c.bb_adaptive_stagnation_nodes=12;c.bb_adaptive_cooldown_nodes=12;c.legacy_mode=false;c.run_mode="ga";return c;}
void writeRun(const std::string& out,const Loaded& L,const Config& c,const Solution& sol,GeneticAlgorithm& ga,const PostProcessor& pp,double wall,double dist,int seed,double p,double cap){Parts z=objectiveParts(L.inst,sol,c);auto cr=pp.getCarbonResult();auto em=emissionParts(L.inst,pp);double total=z.revenue-z.facility-z.inventory-z.supplier-z.market-z.investment+p*cap;double emsum=em.facility+em.inventory+em.supplier+em.market;std::vector<int>open,served,unserved;std::vector<std::string>openId,servedId,unservedId;for(const auto&d:pp.dcResults){if(d.isOpen){open.push_back(d.index);openId.push_back(L.dc[d.index]);for(int i:d.servedRetailers){served.push_back(i);servedId.push_back(L.market[i]);}}}for(int i=0;i<L.inst.numRetailer;++i)if(std::find(served.begin(),served.end(),i)==served.end()){unserved.push_back(i);unservedId.push_back(L.market[i]);}double Dtot=0;double wOpen=0;for(const auto&d:pp.dcResults)if(d.isOpen){wOpen+=d.w;Dtot+=d.D;}double wDemand=0;for(size_t j=0;j<sol.w.size();++j){double d=0;for(const auto&dc:pp.dcResults)if(dc.index==(int)j)d=dc.D;wDemand+=d*sol.w[j];}if(Dtot>0)wDemand/=Dtot;double err=sol.totalProfit-total;std::ofstream r(out+"/result.csv");r<<"outer_status,final_inner_bp_status,integer_solution,relative_gap,termination_reason,wall_time_sec,ga_generations,actual_bp_calls,fitness_cache_hits,cg_iterations,branch_nodes,num_open_dcs,open_dc_indices,open_dc_ids,num_served_markets,served_market_indices,served_market_ids,num_unserved_markets,unserved_market_indices,unserved_market_ids,mean_w_open_dcs,demand_weighted_mean_w,max_w,min_w,revenue,facility_fixed_cost,inventory_cost,supplier_dc_transport_cost,dc_market_transport_cost,total_transport_cost,investment_cost,carbon_trading_cost,reported_total_profit,recomputed_total_profit,objective_decomposition_error,facility_emission,inventory_emission,supplier_dc_transport_emission,dc_market_transport_emission,total_emission,emission_decomposition_error,carbon_quota,allowance_shortage,allowance_surplus,net_carbon_trading_cost,best_w\n";auto* mon=ga.getMonitor();int cg=mon?mon->columnGenIterations():0;int nodes=mon?mon->totalBranchNodes():0;r<<"HEURISTIC_BEST_FOUND,"<<solveStatusName(sol.solveStatus)<<","<<(sol.hasIntegerSolution?"true":"false")<<","<<sol.relativeGap<<",COMPLETED,"<<wall<<","<<ga.getConvergence().size()<<","<<ga.getFitnessBPSolves()<<","<<ga.getActualFitnessCacheHits()<<","<<cg<<","<<nodes<<","<<open.size()<<",\""<<join(open)<<"\",\""<<joinS(openId)<<"\","<<served.size()<<",\""<<join(served)<<"\",\""<<joinS(servedId)<<"\","<<unserved.size()<<",\""<<join(unserved)<<"\",\""<<joinS(unservedId)<<"\","<<(open.empty()?0:wOpen/open.size())<<","<<wDemand<<","<<*std::max_element(sol.w.begin(),sol.w.end())<<","<<*std::min_element(sol.w.begin(),sol.w.end())<<","<<z.revenue<<","<<z.facility<<","<<z.inventory<<","<<z.supplier<<","<<z.market<<","<<z.supplier+z.market<<","<<z.investment<<","<<cr.netCost<<","<<sol.totalProfit<<","<<total<<","<<err<<","<<em.facility<<","<<em.inventory<<","<<em.supplier<<","<<em.market<<","<<cr.E<<","<<emsum-cr.E<<","<<cap<<","<<cr.e_plus<<","<<cr.e_minus<<","<<cr.netCost<<",\"";for(size_t i=0;i<sol.w.size();++i){if(i)r<<";";r<<sol.w[i];}r<<"\"\n";SolutionHelper::saveConvergenceCSV(out+"/convergence.csv",ga.getConvergence());std::ofstream n(out+"/normalized_result.csv");n<<"status,total_profit,inner_bp_status,outer_outcome\nPASS,"<<sol.totalProfit<<","<<solveStatusName(sol.solveStatus)<<",HEURISTIC_BEST_FOUND\n";std::ofstream o(out+"/objective_decomposition.csv");o<<"component,value\nrevenue,"<<z.revenue<<"\nfacility_fixed_cost,"<<z.facility<<"\ninventory_cost,"<<z.inventory<<"\nsupplier_dc_transport_cost,"<<z.supplier<<"\ndc_market_transport_cost,"<<z.market<<"\ntotal_transport_cost,"<<z.supplier+z.market<<"\ninvestment_cost,"<<z.investment<<"\ncarbon_trading_cost,"<<cr.netCost<<"\nreported_total_profit,"<<sol.totalProfit<<"\nrecomputed_total_profit,"<<total<<"\nobjective_decomposition_error,"<<err<<"\n";std::ofstream e(out+"/emission_decomposition.csv");e<<"component,value\nfacility_emission,"<<em.facility<<"\ninventory_emission,"<<em.inventory<<"\nsupplier_dc_transport_emission,"<<em.supplier<<"\ndc_market_transport_emission,"<<em.market<<"\ntotal_emission,"<<cr.E<<"\nemission_decomposition_error,"<<emsum-cr.E<<"\n";std::ofstream map(out+"/index_id_mapping.csv");map<<"dc_index,dc_id\n";for(int j=0;j<L.inst.numDC;++j)map<<j<<","<<L.dc[j]<<"\n";std::ofstream ma(out+"/market_assignment.csv");ma<<"market_index,market_id,assigned_dc_index,assigned_dc_id,served\n";for(int i=0;i<L.inst.numRetailer;++i){int a=-1;for(const auto&d:pp.dcResults)if(std::find(d.servedRetailers.begin(),d.servedRetailers.end(),i)!=d.servedRetailers.end())a=d.index;ma<<i<<","<<L.market[i]<<","<<a<<","<<(a>=0?L.dc[a]:"")<<","<<(a>=0?"true":"false")<<"\n";}std::ofstream rep(out+"/report.txt");rep<<"outer_status=HEURISTIC_BEST_FOUND\nfinal_inner_bp_status="<<solveStatusName(sol.solveStatus)<<"\ninteger_solution="<<(sol.hasIntegerSolution?"true":"false")<<"\nbest_w_length="<<sol.w.size()<<"\n";}
}
int main(int argc,char**argv){try{std::string data=arg(argc,argv,"--data-dir"),out=arg(argc,argv,"--output-dir");double d=std::stod(arg(argc,argv,"--intracity-distance-km","10")),p=std::stod(arg(argc,argv,"--carbon-price","2")),cap=std::stod(arg(argc,argv,"--carbon-quota","14442.842886043889"));int seed=std::stoi(arg(argc,argv,"--random-seed","101"));if(data.empty()||out.empty())throw std::runtime_error("--data-dir and --output-dir required");Loaded L=loadCase(data,d,p,cap,3000,true);if(flag(argc,argv,"--dry-run")){writeDry(out,L,d,cap);std::cout<<"FORMAL_DRY_RUN PASS\n";return 0;}Config c=formalConfig(L.inst,seed,p,cap);std::filesystem::create_directories(out);Logger log;log.init(out+"/run.log",true);Monitor mon;mon.setTotalGenerations(c.max_generation);GeneticAlgorithm ga(c,L.inst);ga.setLogger(&log);ga.setMonitor(&mon);auto t=std::chrono::steady_clock::now();Solution sol=ga.run();double wall=std::chrono::duration<double>(std::chrono::steady_clock::now()-t).count();sol.w=ga.getBestW();if(!sol.hasIntegerSolution||sol.solveStatus!=SolveStatus::OPTIMAL){std::cerr<<"FORMAL_STOP non-optimal inner BP or no integer solution\n";return 4;}PostProcessor pp(L.inst,sol,ga.getBestW());pp.compute();writeRun(out,L,c,sol,ga,pp,wall,d,seed,p,cap);std::cout<<"FORMAL_PASS seed="<<seed<<" distance="<<d<<" profit="<<sol.totalProfit<<" wall="<<wall<<"\n";return 0;}catch(const std::exception&e){std::cerr<<"ERROR: "<<e.what()<<"\n";return 2;}}
